INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('2025-주-엔에스티-nst공법-시공-신규-사업자-모집', '2025 (주)엔에스티 NST공법 시공 "신규 사업자" 모집', '(주)엔에스티는 새집증후군 개선 전문회사로 20년 노하우가 집약된 새집증후군 개선 시공 방법인 NST공법을 개발한 회사입니다.', '', '<p><strong>(주)엔에스티는 새집증후군 개선 전문회사로 20년 노하우가 집약된 새집증후군 개선 시공 방법인 NST공법을 개발한 회사입니다.</strong></p>
<p><strong>국민 건강을 지키기 위해 함께할 NST공법 시공업체 신규 사업자를 모집합니다.</strong></p>
<p><strong>□ 모집 부문</strong></p>
<ul>
<li>NST공법 시공업체 (새집증후군 예방·개선을 위한 친환경 시공)</li>
</ul>
<p><strong>□ 신청 자격 및 우대 조건</strong></p>
<ul>
<li>입주 청소 시장 3년 이상 경력 보유 업체</li>
<li>대·중형 품목(입주청소, 줄눈, 나노코팅, 방충망, 커튼 등) 시공 경험 보유 업체</li>
<li>입주 박람회 참가 이력 있는 업체</li>
</ul>
<p><strong>□ 신청 방법</strong></p>
<ul>
<li>이메일 문의 : <a href="mailto:isnst@naver.com">isnst@naver.com</a></li>
<li>전화 문의 : 043-222-2322</li>
</ul>
<p><img src="/old/68fdcbc3003ef5404575.webp" alt="2025 전국 신규 사업자 모집 포스터 — NST공법 홍보대사 새지비, 대한민국 환경대상 환경제품 부문 수상(2025년)" width="1127" height="1701"></p>
<p><strong>포스터 내용</strong> — 새집증후군 개선 시공 전문업체 · 2025 전국 신규 사업자 모집 · NST공법 20년 경력 노하우!</p>
<ul>
<li>모집부문(물품공급계약): 새집증후군 개선 “NST공법” 시공 업체</li>
<li>신청자격(우대): 입주시장 3년 이상 경력 업체 · 다(多) 품목(입주청소, 줄눈, 나노코팅, 방충망, 커튼 등) ‘종합업체’ · 입주박람회 참여 업체</li>
<li>신청방법: ① 이메일 문의 isnst@naver.com ② 카카오톡 1:1 채팅(QR 스캔 → 가입문의) ③ 전화문의 (043)222-2322</li>
</ul>', NULL, 'notice', 'published', NULL, '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z');

-- notice-02.md (https://knst.co.kr/nst-notice/?mod=document&uid=2)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('nst새지비-새집증후군-개선-전문업체-주-엔에스티의-nst공법-공식-홍보대사로-탄생하다', '''NST새지비'', 새집증후군 개선 전문업체 (주)엔에스티의 NST공법 공식 홍보대사로 탄생하다!', '(주)엔에스티 NST공법의 얼굴이자, 상징인 “NST새지비” 캐릭터가 드디어 공식 홍보대사로 런칭했습니다! NST새지비는 새집+비전(vision) : 미래 세대를 위한 건강한 주거 비전 의미로 (주)엔에스티 NST공법을 대표하는 홍보대사이자', '', '<p>안녕하세요. (주)엔에스티입니다. 오늘은 특별한 소식을 전해드립니다.</p>
<p>(주)엔에스티 NST공법의 얼굴이자,</p>
<p>상징인 “NST새지비” 캐릭터가 드디어 공식 홍보대사로 런칭했습니다!</p>
<p>NST새지비는 새집+비전(vision) : 미래 세대를 위한 건강한 주거 비전 의미로 (주)엔에스티 NST공법을 대표하는 홍보대사이자</p>
<p>친환경 지식을 공유하며 미래의 주거 문화를 만들어갈 비전의 상징입니다.”</p>
<p><img src="/old/img-288aabcc95.webp" alt="새지비 캐릭터" width="100" height="100"></p>
<p>앞으로 새지비는 블로그와 다양한 콘텐츠에서</p>
<p>NST공법 기술력과 가치를 쉽고 친근하게 전달하고</p>
<p>✅ (주)엔에스티 소개</p>
<p>✅ 새집증후군 예방 NST공법 제품 삼총사(S100, S200, F100) 소개</p>
<p>✅ 친환경 정보</p>
<p>다양한 환경 주제로 활발히 활동 할 예정입니다.</p>
<p>이제 (주)엔에스티의 NST공법 등 친환경 이야기는 &quot;NST새지비&quot;가 함께 합니다.</p>
<p>많은 관심과 응원 부탁드립니다.</p>
<p><a href="https://www.ajunews.com/view/20250915101335572" target="_blank" rel="noopener noreferrer">엔에스티, 전국 신규사업자 모집 본격화… 새집증후군 개선 NST공법 홍보대사 ''새지비'' 런칭 | 아주경제</a></p>
<p><img src="/old/68dfa6ae26a4c8931131.webp" alt="NST공법 공식 홍보대사 새지비 — 집 모양 지붕을 쓴 부엉이 캐릭터" width="1600" height="1600"></p>', NULL, 'notice', 'published', NULL, '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z');

-- notice-03.md (https://knst.co.kr/nst-notice/?mod=document&uid=3)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('nst공법-주-엔에스티-경축-환경부-후원-2025-대한민국환경대상-환경제품-부문-수상', '[NST공법] ㈜엔에스티 "경축", 환경부 후원 「2025 대한민국환경대상」 환경제품 부문 수상!', '새집증후군 예방 업체 중 유일하게 건설사 전세대(100세대 이상) 시공 실적을 보유한 ㈜엔에스티가 지난 7.18 여의도 국회의사당에서 환경부가 후원하는 「2025 대한민국 환경대상」 환경제품 부문 본상을 수상했습니다.', '', '<p>새집증후군 예방 업체 중 유일하게 건설사 전세대(100세대 이상) 시공 실적을 보유한 ㈜엔에스티가 지난 7.18 여의도 국회의사당에서 환경부가 후원하는 「2025 대한민국 환경대상」 환경제품 부문 본상을 수상했습니다.</p>
<p>2025 대한민국 환경대상은 환경부가 후원하며 20년째 이어져 오고 있는 환경분야 대표 시상식으로, 환경 개선과 지속 가능한 미래를 위해 기여한 기업과 기관을 공식적으로 인정하는 자리입니다.</p>
<p>이번 수상은 단순한 상이 아니라, 새집증후군으로 고통받는 수많은 가정과 국민의 생활환경을 개선하기 위해 20여 년간 연구·개발을 이어온 엔에스티의 진정성을 공식적인 자리에서 인정 받은 첫 사례입니다.</p>
<p>많은 관심과 성원에 감사드리며 앞으로도 깨끗한 공기, 건강한 생활환경을 위해 최선을 다하겠습니다.</p>
<p>새집증후군 해결은, NST공법에서 시작됩니다.</p>
<p><img src="/old/68dfa994f326f2046374.webp" alt="2025 대한민국환경대상 시상식 — 상장과 꽃다발을 든 수상 사진" width="600" height="400"></p>
<p><a href="https://www.ksilbo.co.kr/news/articleView.html?idxno=1032425" target="_blank" rel="noopener noreferrer">엔에스티, ''2025 대한민국환경대상'' 본상 수상 &lt; 기업 &lt; 전국뉴스 &lt; 기사본문 - 경상일보</a></p>
<p><a href="https://www.wowtv.co.kr/NewsCenter/News/Read?articleId=A202507210197&amp;t=NN" target="_blank" rel="noopener noreferrer">엔에스티, ''2025 대한민국환경대상'' 환경제품 부문 본상 수상 | 한국경제TV</a></p>
<p><a href="https://www.mydaily.co.kr/page/view/2025072109590976647" target="_blank" rel="noopener noreferrer">㈜엔에스티, `2025 대한민국환경대상` 본상 수상 - 마이데일리</a></p>
<p><a href="https://www.gokorea.kr/news/articleView.html?idxno=833287" target="_blank" rel="noopener noreferrer">㈜엔에스티,「2025 대한민국환경대상」본상 수상 &lt; 오늘공감 &lt; 기사본문 - 공감신문</a></p>
<p><a href="https://www.ziksir.com/news/articleView.html?idxno=97759" target="_blank" rel="noopener noreferrer">엔에스티, 2025 대한민국환경대상 본상 수상</a></p>', NULL, 'notice', 'published', NULL, '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z', '2025-10-03T00:00:00.000Z');

-- notice-04.md (https://knst.co.kr/nst-notice/?mod=document&uid=4)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('공식-새집증후군-개선-nst공법-시공업체-알림', '[공식]새집증후군 개선 NST공법 시공업체 알림', '이번에 홈페이지를 리뉴얼 하면서 NST공법 시공 업체 현황을 업데이트 하였기에 알려드립니다 왜? NST공법 시공업체 확인이 중요할까요? NST공법은 단순한 제품 뿌리기가 아닙니다.', '', '<p>안녕하세요, (주)엔에스티 입니다.</p>
<p>이번에 홈페이지를 리뉴얼 하면서 NST공법 시공 업체 현황을 업데이트 하였기에 알려드립니다</p>
<p>왜? NST공법 시공업체 확인이 중요할까요? NST공법은 단순한 제품 뿌리기가 아닙니다.</p>
<p>인증된 제품 기술과 시공 메뉴얼이 필요한 정밀한 새집증후군 개선 공법 입니다.</p>
<p><img src="/old/notice-04-inline-1.webp" alt="NST공법 시공 업체 현황 지도 (25.10.28 기준)" width="1567" height="1573"></p>
<h3>NST공법 시공 업체 현황 (지도 표기 25.10.28)</h3>
<ul>
<li><strong>서울(4)</strong>: 네오하우스 · 도봉구 / 이온크린 · 용산구 / 이삭엔에스티 · 송파구 / 파란공간 · 강남구</li>
<li><strong>경기(8)</strong>: NST힐링하우스 · 남양주 / THE CLASS · 시흥시 / 성실깔끄미 · 김포시 / 숲속이야기(경기) · 파주시 / 청소남자(신규) · 파주시 / 스토리샵 · 남양주 / 아이앤아이 · 오산시 / ㈜영우 · 의정부시</li>
<li><strong>인천(2)</strong>: PK CLASS · 서구 / 감성홈케어 · 서구</li>
<li><strong>충북/충남/세종/대전(5)</strong>: 네오그린 · 충북 청주시 / 슈퍼빗자루 · 충북 청주시 / 에코그린 · 세종시 / 청소PRO · 대전시 / 별별청소 · 충남 서산시</li>
<li><strong>경북/대구/울산(2)</strong>: 숲속이야기 · 경북 구미 / 클린868 · 대구 달서구</li>
<li><strong>전북/전남/광주(1)</strong>: 태양홈케어 · 전북 군산시</li>
<li><strong>강원 · 경남/부산 · 제주</strong>: 모집중</li>
</ul>
<blockquote>
<p>NST공법 전문 시공업체 확인은 선택이 아닌 필수 입니다.</p>
<p>반드시 홈페이지에 있는 시공업체를 확인하세요!!</p>
</blockquote>
<p>시공업체 | (주)엔에스티</p>
<p><a href="/partners/">knst.co.kr/partners/</a> </p>
<p>다음과 같은 경우는 정식 시공팀이 아닐 가능성이 높습니다</p>
<ol>
<li>
<p>시공업체 명단 없는 업체</p>
</li>
<li>
<p>NST-S100, NST-S200, NST-F100 아닌 다른 제품으로 시공하는 업체</p>
</li>
<li>
<p>NST공법 시공 후 연락두절</p>
</li>
</ol>
<p>고객님의 안전한 선택을 위해 반드시 공식 홈페이지 시공업체를 확인해주세요.</p>
<p>감사합니다.</p>', NULL, 'notice', 'published', NULL, '2025-10-10T00:00:00.000Z', '2025-10-10T00:00:00.000Z', '2025-10-10T00:00:00.000Z');

-- notice-05.md (https://knst.co.kr/nst-notice/?mod=document&uid=5)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('공지-입주시장-전문업체-청소남자-c-m-계약-체결', '[공지]입주시장 전문업체 ''청소남자 C&M'' 계약 체결', '홈케어 전문 ‘청소남자C&M’과 계약을 체결하였습니다. 동 계약으로 새집증후군 개선 서비스를 제공하게 됩니다.', '', '<p>홈케어 전문 <strong>‘청소남자C&amp;M’과 계약을 체결하였습니다.</strong></p>
<p>동 계약으로 <strong>새집증후군 개선 서비스</strong>를 제공하게 됩니다.</p>
<h3>🤝 계약 개요</h3>
<ul>
<li>
<p><strong>계약 일자 :</strong> 2025년 10월 27일</p>
</li>
<li>
<p><strong>계약 당사자 :</strong> ㈜엔에스티 × 청소남자C&amp;M</p>
<p> [연락처] 010-8186-0027, 010-6689-4180</p>
<p> [품목] 새집증후군, 입주청소, 줄눈, 코팅</p>
</li>
</ul>
<p><strong>실력있는 사업자와 NST공법 시공 네트워크</strong>를 강화합니다.</p>
<p>우리가족! 우리아이! 건강을 계속 지켜 나가겠습니다.</p>', NULL, 'notice', 'published', NULL, '2025-10-28T00:00:00.000Z', '2025-10-28T00:00:00.000Z', '2025-10-28T00:00:00.000Z');

