-- news-434-엔에스티-2025-대한민국환경대상-수상.md (https://knst.co.kr/news/%ec%97%94%ec%97%90%ec%8a%a4%ed%8b%b0-2025-%eb%8c%80%ed%95%9c%eb%af%bc%ea%b5%ad%ed%99%98%ea%b2%bd%eb%8c%80%ec%83%81-%ec%88%98%ec%83%81/)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('주-엔에스티-2025-대한민국환경대상-환경제품-부문-본상-수상', '(주)엔에스티, ‘2025 대한민국환경대상’ 환경제품 부문 본상 수상', '새집증후군 예방 및 실내공기질 개선 제품을 개발·시공하는 전문기업인 ㈜엔에스티(대표 김용득)는 지난 18일, 국회의사당 국회헌정기념관에서 개최된 ‘2025 대한민국환경대상’ 시상식에서 ‘환경제품 부문 본상’을 수상했다.', '', '<p>새집증후군 예방 및 실내공기질 개선 제품을 개발·시공하는 전문기업인 ㈜엔에스티(대표 김용득)는 지난 18일, 국회의사당 국회헌정기념관에서 개최된 ‘2025 대한민국환경대상’ 시상식에서 ‘환경제품 부문 본상’을 수상했다. 동 시상식은 올해 20번째 개최되는 행사로 환경부를 비롯한 5개 정부 부처가 후원하고 지속가능한 미래를 위한 친환경 기술과 사회적 기여도를 종합적으로 평가해 수상자를 선정하는 국내 대표적인 환경 분야 시상식이다. 엔에스티 제품 3총사(NST-S100, S200, F100)를 활용한 복합 솔루션을 통해 실내 공간의 유해물질 발생을 원천 차단하고 공기 정화 효과를 구현해 국민 건강에 이바지하여 금번 환경제품 부문 본상을 수상 하게 되었다.</p>
<p><a href="https://www.wowtv.co.kr/NewsCenter/News/Read?articleId=A202507210197&amp;t=NN" target="_blank" rel="noopener noreferrer">※출처 : 엔에스티, ‘2025 대한민국환경대상’ 환경제품 부문 본상 수상 | 한국경제TV</a></p>', NULL, 'news', 'published', 'https://www.wowtv.co.kr/NewsCenter/News/Read?articleId=A202507210197&t=NN', '2025-07-21T00:00:00.000Z', '2025-07-21T00:00:00.000Z', '2025-07-21T00:00:00.000Z');

-- news-165-뉴스-02.md (https://knst.co.kr/news/%eb%89%b4%ec%8a%a4-02/)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('엔에스티-전국-신규사업자-모집-본격화-nst공법-홍보대사-새지비-런칭', '엔에스티, 전국 신규사업자 모집 본격화… NST공법 홍보대사 ‘새지비’ 런칭', '새집증후군 개선 전문기업 엔에스티가 전국 신규사업자 모집에 본격적으로 나섰다. 20년간의 노하우를 집약한 기술 NST공법의 리뉴얼 신제품을 지난 8월에 출시한 데 이어 사업 확대 일환으로 신규사업자 네트워크를 강화하며 시장 점유율 확대에 속도를 올리고 있다.', '', '<p>새집증후군 개선 전문기업 엔에스티가 전국 신규사업자 모집에 본격적으로 나섰다. 20년간의 노하우를 집약한 기술 NST공법의 리뉴얼 신제품을 지난 8월에 출시한 데 이어 사업 확대 일환으로 신규사업자 네트워크를 강화하며 시장 점유율 확대에 속도를 올리고 있다.</p>
<p>동시에, 브랜드 가치를 높이고 소비자와 소통을 강화하기 위해 NST공법 공식 홍보대사 ‘새지비’도 런칭하며, 미래 세대 친환경 주거 문화 확산에 기틀을 다졌다.</p>
<p>※출처 : <a href="https://www.ajunews.com/view/20250915101335572" target="_blank" rel="noopener noreferrer">엔에스티, 전국 신규사업자 모집 본격화… 새집증후군 개선 NST공법 홍보대사 ‘새지비’ 런칭 | 아주경제</a></p>', NULL, 'news', 'published', 'https://www.ajunews.com/view/20250915101335572', '2025-09-16T00:00:00.000Z', '2025-09-16T00:00:00.000Z', '2025-09-16T00:00:00.000Z');

-- news-163-뉴스-01.md (https://knst.co.kr/news/%eb%89%b4%ec%8a%a4-01/)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('주-엔에스티-새집증후군-개선-전문기술-nst공법-하이앤드-듀얼-신제품-3종-출시', '㈜엔에스티, 새집증후군 개선 전문기술 NST공법 ‘하이앤드 듀얼’ 신제품 3종 출시', '㈜엔에스티는 대형건설사 아파트 전세대 일괄시공(1,018세대 외 다수)으로 검증한 노하우를 바탕으로 NST공법 전용 ‘하이앤드 듀얼’ 신제품 3종을 출시했다.', '', '<p>□  ㈜엔에스티는 대형건설사 아파트 전세대 일괄시공(1,018세대 외 다수)으로 검증한 노하우를 바탕으로 NST공법 전용 ‘하이앤드 듀얼’ 신제품 3종을 출시했다.</p>
<p> □  신제품은 단기 탈취가 아닌 <strong>시간이 지나도 효과가 유지되는 지속형 새집증후군 관리 기술</strong>을 표준화하는 데 초점을 맞췄다.</p>
<p> □  NST-S100은 빛 유무에 따라 포집·분해가 자동 전환되는 듀얼 촉매 기술로 24시간 공기질 관리를 구현한다.</p>
<p> □  NST-S200과 F100은 방출원 안정화와 사각지대 보완을 통해 재방출을 억제하고 체감 만족도를 높인다.</p>
<p> □  엔에스티는 남부권을 중심으로 검증된 기술 기반의 신규 시공 파트너를 모집해 서비스망을 확대한다.</p>
<p> ※출처 :</p>
<p><a href="https://www.kbsm.net/news/view.php?idx=506398" target="_blank" rel="noopener noreferrer">엔에스티, 새집증후군 개선 전문기술 NST공법 ‘하이앤드 듀얼’ 신제품 3종 출시 – 경북신문</a></p>
<p><a href="https://www.gokorea.kr/news/articleView.html?idxno=855770" target="_blank" rel="noopener noreferrer">㈜엔에스티, 새집증후군 개선 전문기술 NST공법 ‘하이앤드 듀얼’ 신제품 3종 출시 &lt; 오늘공감 &lt; 기사본문 – 공감신문</a></p>
<p><a href="https://www.vegannews.co.kr/news/article.html?no=381360" target="_blank" rel="noopener noreferrer">㈜엔에스티, 새집증후군 관리 ‘하이앤드 듀얼’ 3종 출시</a></p>', NULL, 'news', 'published', 'https://www.kbsm.net/news/view.php?idx=506398', '2026-01-28T00:00:00.000Z', '2026-01-28T00:00:00.000Z', '2026-01-28T00:00:00.000Z');

-- post-4586-nst공법-소개.md (https://knst.co.kr/nst%ea%b3%b5%eb%b2%95-%ec%86%8c%ea%b0%9c/)
INSERT OR IGNORE INTO posts (slug, title, excerpt, content_md, content_html, cover_image, category, status, source_url, published_at, created_at, updated_at) VALUES
  ('nst공법이란-주-엔에스티-새집증후군-전문-기술-소개', 'NST공법이란? | (주)엔에스티 새집증후군 전문 기술 소개', '일시적인 냄새 완화에 그치기 쉬운 단순 피톤치드나 숯 비치, 그리고 근본적인 원인 차단에 구조적 한계가 있는 일반적인 베이크아웃과 입주청소만으로는 새집증후군을 완벽히 해결하기 어렵습니다.', '', '<p>일시적인 냄새 완화에 그치기 쉬운 단순 피톤치드나 숯 비치, 그리고 근본적인 원인 차단에 구조적 한계가 있는 일반적인 베이크아웃과 입주청소만으로는 새집증후군을 완벽히 해결하기 어렵습니다. (주)엔에스티는 수만 세대의 대형 아파트 일괄 시공 실적과 특허받은 <strong>NST공법(NST-S100, S200, F100)</strong>으로 포름알데히드와 VOCs를 뿌리 뽑는 진짜 솔루션을 제시합니다.</p>
<h2>NST공법 (NST Technology)</h2>
<p>(주)엔에스티가 개발·운영하는 <strong>새집증후군 예방 및 실내공기질 전문 관리 기술</strong>입니다. 포름알데히드·VOCs 등 가스상 유해물질의 방출원을 구조적으로 안정화하여 근본적인 실내공기질 개선을 실현합니다.</p>
<h4>💡 전문가의 핵심 팩트 체크 (LSI &amp; 검증)</h4>
<p>신혼집 인테리어나 신축 아파트 입주 시 가장 주의해야 할 것은 눈에 보이지 않는 <strong>1급 발암물질</strong>입니다. 시중의 값싼 방향제나 환기만으로는 가구의 MDF, 파티클보드 안쪽에서 수년 동안 뿜어져 나오는 포름알데히드를 막을 수 없습니다.</p>
<p>저희 (주)엔에스티는 <strong>조작 불가능한 국가 공인 실내공기질 공정시험방법</strong>을 통과하였으며, 시공 전 과정을 고객이 직접 100% 현장에서 참관할 수 있도록 투명하게 공개합니다. 이것이 바로 환경부 전임 장차관들이 심사하여 환경대상을 수여한 기술의 자신감입니다.</p>
<h3>(주)엔에스티 프리미엄 객관적 증거</h3>
<p>말로만 하는 퍼포먼스가 아닌, 수많은 언론과 국가 공인 시험이 증명합니다.</p>
<ul>
<li><strong>원천 특허 기술:</strong> 고성능 가시광촉매(NST-S100), 구조안정화 및 유해물질 차단·제거제(S200), 그리고 포름알데히드 제거제(F100) 보유</li>
<li><strong>2025 대한민국환경대상:</strong> 환경부 전임 장차관 위원 심사를 통과한 본상 수상</li>
<li><strong>1급 발암물질 원천 차단:</strong> 대형건설사 전세대 일괄시공(1,018세대 등) 및 까다로운 실내공기질 공정시험방법 통과</li>
<li><strong>투명한 100% 현장 참관:</strong> 간이 측정기로 수치를 조작하는 꼼수를 쓰지 않고, 현장의 땀방울로 정직하게 증명합니다.</li>
<li><strong>20년 새집증후군 외길 :</strong> 연구개발-원료 관리-제품생산-판매-시공까지 직접하는 <strong>업계 유일한 새집증후군 전문업체</strong></li>
</ul>
<h4>📰 국내 주요 언론 보도</h4>
<p>아주경제 2025.09.15</p>
<h4><a href="https://www.ajunews.com/view/20250915101335572" target="_blank" rel="noopener noreferrer">신규사업자 모집 본격화 및 홍보대사 ‘새지비’ 런칭</a></h4>
